// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }
    function testFuzz_property(address caller, bytes32 hash) public {
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        vm.deal(caller, 2 ether);
        vm.prank(caller);
        bool success;
        try c.lockInGuess{value: 1 ether}(hash) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}
